  "name": "megashop",
  "version": "1.0.0",
  "description": "Loja virtual de departamentos",
  "main": "server.js",
  "scripts": {
    "start": "node server.js"
  },
  "dependencies": {
    "express": "^4.18.2",
    "sqlite3": "^5.1.6",
