:root {
    --primary: #2c3e50;
    --accent: #e67e22;
    --bg: #f4f7f6;
    --white: #ffffff;
    --text: #333333;
}

* { box-sizing: border-box; margin: 0; padding: 0; font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif; }
body { background-color: var(--bg); color: var(--text); }

/* Navegação */
.navbar { background: var(--primary); color: var(--white); padding: 1rem 2rem; display: flex; justify-content: space-between; align-items: center; position: sticky; top: 0; z-index: 100; box-shadow: 0 2px 5px rgba(0,0,0,0.1); }
.logo { font-size: 1.5rem; font-weight: bold; cursor: pointer; color: var(--accent); }
.nav-links button { margin-left: 10px; }

.container { max-width: 1200px; margin: 2rem auto; padding: 0 1rem; }
.hidden { display: none !important; }

/* Autenticação */
.auth-box { max-width: 400px; margin: 3rem auto; background: var(--white); padding: 2rem; border-radius: 8px; box-shadow: 0 4px 10px rgba(0,0,0,0.1); display: flex; flex-direction: column; gap: 1rem; }
.auth-box h2 { text-align: center; color: var(--primary); margin-bottom: 1rem;}
.auth-box input { padding: 12px; border: 1px solid #ccc; border-radius: 4px; }
.link { text-align: center; color: var(--primary); cursor: pointer; text-decoration: underline; margin-top: 10px; font-size: 0.9rem;}

/* Botões */
.btn { padding: 10px 15px; border: none; border-radius: 4px; cursor: pointer; font-weight: bold; transition: 0.3s; }
.btn-primary { background: var(--primary); color: white; }
.btn-primary:hover { background: #1a252f; }
.btn-accent { background: var(--accent); color: white; }
.btn-accent:hover { background: #d35400; }
.btn-success { background: #27ae60; color: white; }
.btn-success:hover { background: #2ecc71; }
.btn-danger { background: #c0392b; color: white; }
.btn-danger:hover { background: #e74c3c; }
.btn-outline { background: transparent; border: 1px solid var(--primary); color: var(--primary); margin: 0 5px;}
.btn-outline:hover { background: var(--primary); color: white; }

/* Loja */
.header-store { display: flex; justify-content: space-between; align-items: center; margin-bottom: 2rem; flex-wrap: wrap; gap: 1rem; }
.grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(250px, 1fr)); gap: 1.5rem; }
.card { background: var(--white); border-radius: 8px; overflow: hidden; box-shadow: 0 2px 8px rgba(0,0,0,0.1); display: flex; flex-direction: column; }
.card-img { height: 150px; background: #e0e0e0; display: flex; align-items: center; justify-content: center; color: #999; font-size: 3rem; }
.card-body { padding: 1rem; flex-grow: 1; display: flex; flex-direction: column; }
.card-title { font-size: 1.1rem; margin-bottom: 0.5rem; color: var(--primary); }
.card-dept { font-size: 0.8rem; color: var(--accent); font-weight: bold; margin-bottom: 0.5rem; text-transform: uppercase; }
.card-desc { font-size: 0.9rem; color: #666; margin-bottom: 1rem; flex-grow: 1; }
.card-price { font-size: 1.3rem; font-weight: bold; color: #27ae60; margin-bottom: 1rem; }

/* Painéis e Listas */
.panel { background: var(--white); padding: 2rem; border-radius: 8px; box-shadow: 0 2px 8px rgba(0,0,0,0.1); }
.list-item { border-bottom: 1px solid #eee; padding: 1rem 0; display: flex; justify-content: space-between; align-items: center; flex-wrap: wrap; gap: 10px; }
.cart-total { text-align: right; margin-top: 2rem; padding-top: 1rem; border-top: 2px solid #eee; }

/* Form Admin */
.admin-form { display: flex; flex-direction: column; gap: 10px; margin-bottom: 2rem; background: #f9f9f9; padding: 1.5rem; border-radius: 8px; border: 1px solid #ddd; }
.admin-form input, .admin-form select, .admin-form textarea { padding: 10px; border: 1px solid #ccc; border-radius: 4px; }
.admin-form textarea { min-height: 80px; resize: vertical; }

/* Order Badges */
.badge { padding: 5px 10px; border-radius: 12px; font-size: 0.85rem; font-weight: bold; }
.badge-Pendente { background: #f1c40f; color: #fff; }
.badge-Enviado { background: #3498db; color: #fff; }
.badge-Entregue { background: #2ecc71; color: #fff; }

.order-products { font-size: 0.9rem; color: #555; margin-top: 5px; }
select.order-status { padding: 5px; border-radius: 4px; }
